inline void score_modbus_rf(double* input, double* output) {
 output[0]=output[1]=output[2]=0;
 for (int root: scada_modbus_rf::roots) {
  int i=root;
  while(scada_modbus_rf::nodes[i].left>=0) {
   const auto& n=scada_modbus_rf::nodes[i];
   i=static_cast<float>(input[n.feature])<=n.threshold?n.left:n.right;
  }
  for(int c=0;c<3;c++) output[c]+=scada_modbus_rf::nodes[i].p[c];
 }
 for(int c=0;c<3;c++) output[c]/=100.0;
}
